import io, os
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), "tasks_scored.csv")
with open(out, "w", newline="", encoding="utf-8") as f:
    w = csv.writer(f); w.writerow(["occupation","task","score_0_1_2"])
    n = 0
    for r in csv.reader(io.StringIO(rows), delimiter="|", quotechar='"'):
        w.writerow(r); n += 1
print(n, "rows ->", out)
